"""Sets ENCRYPTION_KEY in the untracked .env if missing; `--print` only prints a new key."""

import sys
from pathlib import Path

from cryptography.fernet import Fernet
from dotenv import dotenv_values

ENV_FILE = Path(__file__).resolve().parents[2] / ".env"


def init(env_file: Path = ENV_FILE) -> bool:
    values = dotenv_values(env_file) if env_file.exists() else {}
    if values.get("ENCRYPTION_KEY"):
        return False
    with env_file.open("a", encoding="utf-8") as env:
        env.write(
            "\n# generated by `make secrets-setup`; back it up, losing it loses every secret\n"
        )
        env.write(f"ENCRYPTION_KEY={Fernet.generate_key().decode()}\n")
    return True


if __name__ == "__main__":
    if "--print" in sys.argv[1:]:
        print(Fernet.generate_key().decode())
    else:
        print(
            "secrets: added ENCRYPTION_KEY to .env"
            if init()
            else "secrets: ENCRYPTION_KEY already set"
        )
